-- cert.sql — área Certificação do LOP - Gestão Rápida (13/10/2026)
-- Rodar uma vez no SQL Editor do Supabase (projeto ysvmfmnwbcxgsrjewwsy).
-- Pode rodar de novo sem estragar nada: cria só o que falta e só carrega os
-- dados iniciais quando a tabela está vazia.
-- Permissão: módulo 'cert' em app_usuarios.modulos (ou administrador).

create table if not exists public.cert_certificacoes (
  id text primary key,                 -- IFA, GRASP, RA, SMETA, ATITUDES
  nome text not null,
  norma text not null,                 -- igual ao campo "norma" das referências
  versao text,
  ativa boolean not null default true, -- a fazenda tem hoje
  certificadora text,
  numero text,                         -- GGN, nº do certificado, código Sedex
  escopo text,
  validade date,
  ultima_auditoria date,
  proxima_auditoria date,
  observacao text,
  ordem int not null default 0,
  atualizado_em timestamptz not null default now()
);

create table if not exists public.cert_requisitos (
  id bigint generated by default as identity primary key,
  tema text not null,
  prioridade text not null default 'Maior' check (prioridade in ('Crítica','Maior','Menor')),
  status text not null default 'Pendente'
    check (status in ('Conforme','Em andamento','Pendente','Não conforme','Não se aplica')),
  titulo text not null,
  descricao text,
  evidencia text,
  referencias jsonb not null default '[]'::jsonb,   -- [{norma, versao, codigo}]
  periodicidade text,
  responsavel text,
  prazo date,
  ultima_verificacao date,
  observacao text,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now(),
  atualizado_por text
);

create table if not exists public.cert_documentos (
  id bigint generated by default as identity primary key,
  codigo text not null,
  nome text not null,
  categoria text not null,             -- ANEXO, INST. TRABALHO, REGISTROS, P.O.Ps, CHECK LIST
  responsavel text,
  periodicidade text,                  -- Diário, Semanal, Mensal, Trimestral, Semestral, Anual
  situacao text not null default 'Em dia' check (situacao in ('Em dia','Revisar','Pendente','Obsoleto')),
  revisao text,
  data_revisao date,
  certificacoes text[] not null default '{}',
  observacao text,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

create table if not exists public.cert_eventos (
  id bigint generated by default as identity primary key,
  data date not null,
  data_fim date,
  tipo text not null default 'Atividade',
  titulo text not null,
  certificacoes text[] not null default '{}',
  responsavel text,
  repetir text,                        -- null | Mensal | Trimestral | Semestral | Anual
  feitos date[] not null default '{}', -- ocorrências dadas como feitas
  observacao text,
  criado_em timestamptz not null default now(),
  criado_por text
);
create index if not exists cert_eventos_data on public.cert_eventos(data);

do $$ declare t text; begin
  foreach t in array array['cert_certificacoes','cert_requisitos','cert_documentos','cert_eventos'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists cert_leem on public.%I', t);
    execute format('drop policy if exists cert_escrevem on public.%I', t);
    execute format('create policy cert_leem on public.%I for select to authenticated using (public.app_pode(''cert''))', t);
    execute format('create policy cert_escrevem on public.%I for all to authenticated using (public.app_pode(''cert'')) with check (public.app_pode(''cert''))', t);
  end loop;
end $$;

