  ('Social', 'Crítica', 'Pendente', 'Trabalhadores migrantes', 'Condições justas de recrutamento e permanência de migrantes.', 'Custeio do deslocamento; contratação na origem; rotina de comunicação; sem retenção de salários/documentos. (Específico ATITUDES)', '[{"norma": "ATITUDES", "versao": "2024", "codigo": "3.1.7"}, {"norma": "ATITUDES", "versao": "2024", "codigo": "3.1.8"}, {"norma": "ATITUDES", "versao": "2024", "codigo": "3.1.10"}, {"norma": "SMETA", "versao": "7.0", "codigo": "10A"}]'::jsonb, null, null),
